"use strict";(self.webpackChunkrithmia=self.webpackChunkrithmia||[]).push([["2951"],{3811(e,a,t){t.r(a),t.d(a,{metadata:()=>n,default:()=>c,frontMatter:()=>s,contentTitle:()=>o,toc:()=>l,assets:()=>d});var n=JSON.parse('{"id":"Past Campaigns/The Flora Fauna and the Ugly/Overview","title":"Background","description":"This story takes place 1109 PD (Post-Departure) from Yadrella.","source":"@site/docs/Past Campaigns/The Flora Fauna and the Ugly/Overview.md","sourceDirName":"Past Campaigns/The Flora Fauna and the Ugly","slug":"/Past Campaigns/The Flora Fauna and the Ugly/Overview","permalink":"/Rithmia/docs/Past Campaigns/The Flora Fauna and the Ugly/Overview","draft":false,"unlisted":false,"editUrl":"https://github.com/TravisH18/Rithmia/tree/main/docs/docs/Past Campaigns/The Flora Fauna and the Ugly/Overview.md","tags":[],"version":"current","frontMatter":{},"sidebar":"settingSidebar","previous":{"title":"Post campaign / tier 4 antics","permalink":"/Rithmia/docs/Past Campaigns/Steampunk Campaign/tier-4"},"next":{"title":"folk-horror","permalink":"/Rithmia/docs/Past Campaigns/The Flora Fauna and the Ugly/plot-hooks/folk-horror"}}'),r=t(4848),i=t(8453);let s={},o="Background",d={},l=[{value:"Major Factions",id:"major-factions",level:2},{value:"The weapons of mass destruction used were as follows (in order).",id:"the-weapons-of-mass-destruction-used-were-as-follows-in-order",level:2},{value:"Abyssal Torrent:",id:"abyssal-torrent",level:3},{value:"Radiant Blight",id:"radiant-blight",level:3},{value:"The Sylvan Purge (Oxygen Destroyer)",id:"the-sylvan-purge-oxygen-destroyer",level:3},{value:"This campaign",id:"this-campaign",level:2}];function h(e){let a={h1:"h1",h2:"h2",h3:"h3",header:"header",p:"p",strong:"strong",...(0,i.R)(),...e.components};return(0,r.jsxs)(r.Fragment,{children:[(0,r.jsx)(a.header,{children:(0,r.jsx)(a.h1,{id:"background",children:"Background"})}),"\n",(0,r.jsx)(a.p,{children:"This story takes place 1109 PD (Post-Departure) from Yadrella."}),"\n",(0,r.jsx)(a.p,{children:'In the millennia after departure from the Dawn Island three grand kingdoms arose from the dirt of creation. The kingdom of land (Hearthstone Realm), the kingdom of water (Tidevault Empire) and the underdark coalition of states(subterranean confederacy). Each with differing ideologies and seeking power over this unexplored world known as Rithmia leads to a centuries long "cold war" with no open active war waged besides a few skirmishes over trade vessels. It is unknown the reason, or who attacked first but insane weapons of magical mass destruction were released simultaneously wiping out vast areas of land and releasing magical radiation over huge areas.'}),"\n",(0,r.jsx)(a.h2,{id:"major-factions",children:"Major Factions"}),"\n",(0,r.jsx)(a.p,{children:"Kingdom of land (Hearthstone Realm): Naturalistic empire of smart tactical guerilla fighters, made up of mostly druids, rangers, and barbarians."}),"\n",(0,r.jsx)(a.p,{children:"Kingdom of water (Tidevault empire): A brutal industrial capitalistic empire who seeks to control trade and movement in general on all waters on Rithmia. Even rivers and landlocked seas in the territory of the kingdom of land"}),"\n",(0,r.jsx)(a.p,{children:"Underdark Coalition (Subterranean confederation): Mageocratic meritocracy devoted to studying, comprised mostly of wizards and artificers who are literally delving deep to see secrets of the universe they wished they had never uncovered. This led to the Open air crusade where the subterranean confederacy turned their attention towards the surface and a large group of the populace turned to religion out of fear of what they had discovered. Only to realize the gods were the reason for their fear."}),"\n",(0,r.jsx)(a.h2,{id:"the-weapons-of-mass-destruction-used-were-as-follows-in-order",children:"The weapons of mass destruction used were as follows (in order)."}),"\n",(0,r.jsx)(a.h3,{id:"abyssal-torrent",children:"Abyssal Torrent:"}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Origin:"})," The Abyssal Torrent was developed as a weapon of the Kingdom of Water, drawing upon the corrupted energies of a powerful underwater ley line. Mages of the kingdom tapped into the very heart of the ocean's magic, twisting it into a destructive force that manifested as a colossal tidal wave infused with dark magic."]}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Affected Area:"})," The Abyssal Torrent struck the entire coastline carving a devastating path of destruction. The impact transformed lush forests into twisted, drowned landscapes and fertile plains into desolate marshes. The once-prosperous cities and villages were swallowed by the surging darkness, leaving behind eerie ruins and haunted shores. The magical aftermath left an otherworldly resonance, causing strange occurrences such as spectral echoes of the tidal wave haunting the affected regions."]}),"\n",(0,r.jsx)(a.p,{children:"This weapon conjured water from a layer of the abyss meaning it did raise the global water level and essentially made the territory of the kingdom of water larger."}),"\n",(0,r.jsx)(a.h3,{id:"radiant-blight",children:"Radiant Blight"}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Origin:"})," Forged in the darkest laboratories of the Kingdom of Water, the Radiant Blight is a sinister creation born out of twisted alchemical experiments and forbidden necromantic rituals. The core of this magical weapon is a pulsating, malevolent crystal known as the Umbral Nexus. The crystal was infused with the essence of the Shadowfell, drawing upon its corrupting energies to create a pervasive and deadly force."]}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Affected Area:"})," The Radiant Blight was unleashed upon the sprawling expanse of the Verdant Expanse, a once-lush region teeming with diverse ecosystems. Now, the land is known as the Shadowed Wastes. The Radiant Blight permeates the air, soil, and water with a perpetual, sickly green glow, casting an ominous pallor over the entire landscape."]}),"\n",(0,r.jsx)(a.p,{children:"Any living beings that remain within the Shadowed Wastes for an extended period undergo grotesque mutations. Twisted creatures roam the desolate terrain, their forms warped and contorted by the corrupting influence of the Radiant Blight. The air crackles with dark energy, and the land itself seems to writhe in perpetual agony."}),"\n",(0,r.jsx)(a.p,{children:"Vegetation, once vibrant and full of life, now manifests as grotesque, thorny growths that seem to pulse with an otherworldly malevolence. The very fabric of reality in the affected area is strained, creating rifts to the Shadowfell that occasionally release spectral horrors into the already nightmarish landscape."}),"\n",(0,r.jsx)(a.p,{children:"The Radiant Blight stands as a testament to the devastating consequences of tampering with dark forces, leaving behind a cursed realm where the boundary between life and death is blurred, and the very essence of the land is forever altered."}),"\n",(0,r.jsx)(a.p,{children:"After these two grand attacks were unleashed just hours apart from eachother the kingdom of land unleashed a vile weapon to simply wipe out the enemy."}),"\n",(0,r.jsx)(a.p,{children:"The pure sorrow of the shadowfell mixed with the alchemical expertise has released Contamination (fantasy radiation) a permanent effect of the impact zones of the radiant blight"}),"\n",(0,r.jsx)(a.h3,{id:"the-sylvan-purge-oxygen-destroyer",children:"The Sylvan Purge (Oxygen Destroyer)"}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Origin"}),": The druids of the Kingdom of Land, pushed to extreme measures in their struggle against the Kingdom of Water, developed the Sylvan Purge as a desperate defense. Drawing upon the primal forces of nature, they harnessed the essence of ancient trees and channeled it through a colossal, enchanted crystal known as the Verdant Heart. This ritualistic fusion of magic and nature resulted in a devastating weapon designed to eradicate aquatic life."]}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Affected Area"}),": The Sylvan Purge was unleashed upon the Verdant Delta, a region where mighty rivers converged, creating a lush and biodiverse ecosystem. However, the aftermath of the Sylvan Purge turned this once-thriving delta into a haunting wasteland. The enchantments within the crystal caused the oxygen in the water to dissipate rapidly, leading to the suffocation of all aquatic life."]}),"\n",(0,r.jsx)(a.p,{children:"Now known as the Blighted Marshes, the area is covered in a sickly green mist that emanates from the corrupted Verdant Heart. Mutated and twisted plants claw at the sky, and the ground is saturated with residual magical radiation. Any attempts to approach the delta result in eerie whispers carried by the wind, warning of the consequences of meddling with the balance of nature. The Sylvan Purge left an enduring scar on the landscape, serving as a cautionary tale about the dangers of wielding unchecked magical power in the name of survival."}),"\n",(0,r.jsx)(a.p,{children:"The Verdant hearts can be enhanced for good and could create a seed for the tree of life they will plant in Azazia eventually to create a tree thousands of feet tall"}),"\n",(0,r.jsx)(a.h2,{id:"this-campaign",children:"This campaign"}),"\n",(0,r.jsx)(a.p,{children:"Our campaign takes place between the use of the raidant blight and the sylvan purge. The party will encounter powerful druids who are developing a strategy to save the land and purge the ocean of corruption and malice."})]})}function c(e={}){let{wrapper:a}={...(0,i.R)(),...e.components};return a?(0,r.jsx)(a,{...e,children:(0,r.jsx)(h,{...e})}):h(e)}},8453(e,a,t){t.d(a,{R:()=>s,x:()=>o});var n=t(6540);let r={},i=n.createContext(r);function s(e){let a=n.useContext(i);return n.useMemo(function(){return"function"==typeof e?e(a):{...a,...e}},[a,e])}function o(e){let a;return a=e.disableParentContext?"function"==typeof e.components?e.components(r):e.components||r:s(e.components),n.createElement(i.Provider,{value:a},e.children)}}}]);